
// Importa a função executar do arquivo de configuração do banco.
// Ela permite executar comandos SQL utilizando o pool de conexões Oracle.
const { executar } = require('./database');

// Função responsável por preparar o banco de dados
// antes de iniciar o servidor.
async function bootstrap() {

    // Array que armazena os comandos SQL que serão executados.
    // Podemos adicionar outras tabelas ou estruturas futuramente.
    const tabelas = [

        // Bloco PL/SQL responsável por tentar criar uma tabela.
        `BEGIN

            // EXECUTE IMMEDIATE permite executar um comando SQL
            // dinâmico dentro de um bloco PL/SQL.
            EXECUTE IMMEDIATE '
                CREATE TABLE EXEMPLO (
                    ID NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
                    NOME VARCHAR2(100) NOT NULL
                )';

        // Caso aconteça algum erro durante a criação:
        EXCEPTION

            // WHEN OTHERS captura qualquer exceção.
            WHEN OTHERS THEN

                // SQLCODE retorna o código do erro ocorrido.
                // -955 significa que o nome do objeto já está sendo utilizado.
                // Nesse caso, a tabela já existe e não precisamos criá-la novamente.
                IF SQLCODE != -955 THEN

                    // Se for qualquer outro erro, ele será lançado novamente.
                    RAISE;

                END IF;

        // Finaliza o bloco PL/SQL.
        END;`
    ];

    // Percorre todos os comandos SQL armazenados no array.
    for (const sql of tabelas) {

        // Executa cada comando utilizando a conexão com o Oracle.
        await executar(sql);
    }

    // Exibe uma mensagem quando todas as operações terminarem.
    console.log('Bootstrap executado com sucesso!');
}

// Exporta a função para que outros arquivos possam utilizá-la.
module.exports = { bootstrap };
